part of 'main.dart';

mixin _Result on _State<Main> {
  /// when definition result is generated by other view like recent_search, favorite_word
  /// textController.value needed to update with corrent keyword
  void onResult() {
    Future.microtask(() {
      if (textController.text != searchQuery) {
        textController.text = searchQuery;
      }
    });
  }

  void onSwitchFavorite() {
    app.data.favoriteSwitch(searchQuery);
    app.state.notify();
  }

  bool onDeleteRecents(String str) => data.boxOfRecentSearch.delete(str);

  Widget _resultEmptyQuery() {
    return ViewFeedbacks.message(
      label: lang.searchNoQuery,
    );
  }

  Widget _resultEmpty() {
    return CustomScrollView(
      key: const PageStorageKey('search-result-none'),
      slivers: [
        ViewFeedbacks(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                lang.searchNoMatch,
                style: state.style.labelMedium,
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _resultBlock(ConclusionType o) {
    return CustomScrollView(
      key: PageStorageKey('search-suggest-${o.query}'),
      // controller: scrollController,
      slivers: [
        ViewLists.separator(
          itemBuilder: (BuildContext context, int index) {
            return _resultContainer(o.raw.elementAt(index));
          },
          itemSnap: const ListTile(
            contentPadding: EdgeInsets.symmetric(horizontal: 25, vertical: 8),
            leading: Icon(Icons.north_east_rounded),
          ),
          separator: (BuildContext context, int index) {
            return const ViewDividers();
          },
          itemCount: o.raw.length,
        ),
      ],
    );
  }

  Widget _resultContainer(Map<String, dynamic> item) {
    return ListBody(
      children: <Widget>[
        _wordContainer(item['word']),
        ListView.builder(
          // key: UniqueKey(),
          shrinkWrap: true,
          primary: false,
          itemCount: item['sense'].length,
          padding: EdgeInsets.zero,
          physics: const NeverScrollableScrollPhysics(),
          // padding: EdgeInsets.zero,
          itemBuilder: (context, index) => _senseContainer(item['sense'].elementAt(index)),
        ),
        // _thesaurusContainer(item['thesaurus'])
        _thesaurusContainer(item['word']),
      ],
    );
  }

  Widget _wordContainer(String word) {
    return ListTile(
      // contentPadding: const EdgeInsets.symmetric(vertical: 8, horizontal: 10),
      leading: ViewLabels(
        icon: Icons.campaign_rounded,
        iconColor: state.theme.shadowColor,
        // alignment: Alignment.center,
        iconSize: 30,
      ),
      title: Text(
        word,
        semanticsLabel: word,
        style: state.style.headlineSmall,
      ),
      trailing: ViewButtons(
        onPressed: onSwitchFavorite,
        child: Selector<Core, bool>(
          selector: (_, e) => e.searchQueryFavorited,
          builder: (BuildContext context, bool isFavorited, Widget? child) {
            return Icon(
              Icons.favorite,
              color: isFavorited ? Theme.of(context).highlightColor : null,
            );
          },
        ),
      ),
      onTap: () {
        app.speech.speak(word);
      },
    );
  }

  Widget _senseContainer(Map<String, dynamic> sense) {
    return Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          _posContainer(sense['pos']),
          _clueContainer(sense['clue']),
        ],
      ),
    );
  }

  Widget _posContainer(String pOS) {
    return Container(
      padding: const EdgeInsets.only(top: 10, bottom: 10, left: 25, right: 35),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surface.withOpacity(0.4),
        // color: Theme.of(context).backgroundColor.withOpacity(0.4),
        borderRadius: const BorderRadius.only(
          bottomRight: Radius.circular(100),
        ),
        boxShadow: [
          BoxShadow(
            blurRadius: 0.0,
            color: Theme.of(context).colorScheme.surface.withOpacity(0.7),
            spreadRadius: 0.7,
            offset: const Offset(0.2, .2),
          ),
        ],
      ),
      child: Text(
        pOS,
        semanticsLabel: pOS,
        style: const TextStyle(),
      ),
    );
  }

  Widget _clueContainer(List<Map<String, dynamic>> clue) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 15, horizontal: 5),
      child: ListView.builder(
        shrinkWrap: true,
        primary: false,
        itemCount: clue.length,
        padding: EdgeInsets.zero,
        physics: const NeverScrollableScrollPhysics(),
        itemBuilder: (BuildContext context, int index) {
          return ListBody(
            children: <Widget>[
              _clueMeaning(clue[index]['mean']),
              _examContainer(clue[index]['exam']),
            ],
          );
        },
      ),
    );
  }

  Widget _clueMeaning(String mean) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        Expanded(
          flex: 1,
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 11),
            child: Icon(
              Icons.fiber_manual_record_outlined,
              size: 12,
              color: Theme.of(context).primaryColorDark,
            ),
          ),
        ),
        Expanded(
          flex: 10,
          child: Highlight(
            str: mean,
            search: onSearch,
            style: context.style.bodyLarge!,
          ),
        ),
      ],
    );
  }

  Widget _examContainer(List<dynamic>? exam) {
    if (exam == null || exam.isEmpty) {
      return Container();
    }
    return Container(
      margin: const EdgeInsets.symmetric(vertical: 7, horizontal: 16),
      decoration: BoxDecoration(
        border: Border(
          left: BorderSide(color: Theme.of(context).primaryColorDark, width: 0.4),
        ),
      ),
      child: ListView.builder(
        shrinkWrap: true,
        primary: false,
        itemCount: exam.length,
        physics: const NeverScrollableScrollPhysics(),
        padding: EdgeInsets.zero,
        itemBuilder: (context, index) {
          return Row(
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Expanded(
                flex: 1,
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  child: Icon(
                    Icons.circle,
                    size: 7,
                    color: Theme.of(context).colorScheme.surface,
                  ),
                ),
              ),
              Expanded(
                flex: 8,
                child: Highlight(
                  str: exam[index],
                  search: onSearch,
                  // style: const TextStyle(
                  //   fontWeight: FontWeight.w300,
                  //   fontSize: 17,
                  // ),
                  style: context.style.bodySmall!,
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _thesaurusContainer(String keyword) {
    return FutureBuilder<List<Map<String, Object?>>>(
      future: Provider.of<Core>(context, listen: false).thesaurusGenerate(keyword),
      builder: (BuildContext context, AsyncSnapshot<List<Map<String, Object?>>> snapshot) {
        switch (snapshot.connectionState) {
          case ConnectionState.done:
            return Padding(
              padding: const EdgeInsets.symmetric(vertical: 20, horizontal: 20),
              child: Wrap(
                alignment: WrapAlignment.center,
                crossAxisAlignment: WrapCrossAlignment.center,
                textDirection: TextDirection.ltr,
                spacing: 10,
                runSpacing: 10,
                children: snapshot.data!.map(
                  (e) {
                    return ViewButtons(
                      color: Theme.of(context).colorScheme.surface,
                      borderRadius: const BorderRadius.all(Radius.circular(100.0)),
                      // constraints: const BoxConstraints(maxHeight: 43),
                      child: ViewLabels(
                        labelPadding: const EdgeInsets.symmetric(
                          horizontal: 15,
                          vertical: 3,
                        ),
                        label: e['word'].toString(),
                        labelStyle: const TextStyle(
                          fontSize: 22,
                          fontWeight: FontWeight.w300,
                        ),
                      ),
                      onPressed: () => onSearch(e['word'].toString()),
                    );
                  },
                ).toList(),
              ),
            );
          default:
            return const SizedBox();
        }
      },
    );
  }
}
